package szept.crypto

import org.json.JSONObject
import java.io.ByteArrayInputStream
import java.io.ByteArrayOutputStream
import java.io.File
import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals

/** Matches proto/testdata/vectors.json, generated by the Go reference (proto/vectors_test.go). */
class VectorsTest {
    private val v = JSONObject(File(System.getProperty("vectors")).readText())

    private fun JSONObject.hex(k: String) = unhex(getString(k))

    private fun seq(start: Int, n: Int) = ByteArray(n) { (start + it).toByte() }

    private val p = v.getJSONObject("Pairing")
    private val pa = Pairing.fromSecrets(p.hex("AE"), p.hex("AR"), "https://a.example", "Alice")
    private val pb = Pairing.fromSecrets(p.hex("BE"), p.hex("BR"), "https://b.example", "Bob", seq(0x90, 16))

    @Test
    fun qrCodes() {
        assertEquals(p.getString("AQR"), pa.offer.encode())
        assertEquals(p.getString("BQR"), pb.offer.encode())
        val b = Offer.decode(p.getString("BQR"))
        assertContentEquals(pb.offer.e, b.e)
        assertEquals("Bob", b.name)
        assertContentEquals(seq(0x90, 16), b.invite)
        assertEquals(p.getString("BQR"), b.encode())
    }

    @Test
    fun pairingKeys() {
        val ka = pa.complete(Offer.decode(p.getString("BQR")))
        assertContentEquals(p.hex("Root"), ka.root)
        assertEquals(p.getBoolean("ALo"), ka.isLo)
        assertContentEquals(p.hex("ASendCK"), ka.sendCk)
        assertContentEquals(p.hex("ARecvCK"), ka.recvCk)
        assertContentEquals(p.hex("ASendMbox"), ka.sendMbox)
        assertContentEquals(p.hex("ARecvMbox"), ka.recvMbox)
        assertContentEquals(p.hex("ASendToken"), ka.sendToken)
        assertContentEquals(p.hex("ARecvToken"), ka.recvToken)
        assertEquals(p.getJSONArray("Confirm").toList(), ka.confirm)

        // B sees the mirror image.
        val kb = pb.complete(pa.offer)
        assertContentEquals(ka.root, kb.root)
        assertEquals(!ka.isLo, kb.isLo)
        assertContentEquals(ka.sendCk, kb.recvCk)
        assertContentEquals(ka.sendMbox, kb.recvMbox)
        assertContentEquals(ka.sendToken, kb.recvToken)
        assertEquals(ka.confirm, kb.confirm)
    }

    @Test
    fun ratchet() {
        val r = v.getJSONObject("Ratchet")
        val c = SendChain(r.hex("CK0"))
        val mks = r.getJSONArray("MK")
        for (i in 0 until mks.length()) {
            val (mk, n) = c.next()
            assertEquals(i.toLong(), n)
            assertContentEquals(unhex(mks.getString(i)), mk)
        }
        assertContentEquals(r.hex("CK3"), c.ck)
        val (key, nonce) = messageKeyNonce(unhex(mks.getString(0)))
        assertContentEquals(r.hex("MsgKey0"), key)
        assertContentEquals(r.hex("MsgNonce0"), nonce)
    }

    @Test
    fun pairwise() {
        val w = v.getJSONObject("Pairwise")
        val ka = pa.complete(pb.offer)
        val kb = pb.complete(pa.offer)
        val plaintext = w.hex("Plaintext")
        val msg = Cbor.encode(mapOf("t" to "text", "id" to seq(0xa0, 16), "ts" to 1700000000000L, "body" to "cześć"))
        assertContentEquals(plaintext, msg)
        assertContentEquals(w.hex("Envelope"), Envelope.sealPairwise(SendChain(ka.sendCk), ka.sendMbox, plaintext))
        val opened = Envelope.openPairwise(RecvChain(kb.recvCk), kb.recvMbox, w.hex("Envelope"))
        assertContentEquals(plaintext, opened)
        assertEquals("cześć", Cbor.decodeMap(opened)["body"])
    }

    @Test
    fun group() {
        val g = v.getJSONObject("Group")
        val sPub = Envelope.groupPublicKey(g.hex("SSeed"))
        assertContentEquals(g.hex("Hint"), Envelope.groupHint(g.hex("GK"), sPub))
        val epoch = g.getLong("Epoch")
        val env = Envelope.sealGroup(SendChain(g.hex("CK0")), g.hex("GK"), g.hex("GID"), epoch, g.hex("SSeed"), g.hex("Plaintext"))
        assertContentEquals(g.hex("Envelope"), env)
        assertContentEquals(g.hex("Hint"), Envelope.groupHeader(env).hint)
        val opened = Envelope.openGroup(RecvChain(g.hex("CK0")), g.hex("GID"), epoch, sPub, env)
        assertContentEquals(g.hex("Plaintext"), opened)
    }

    @Test
    fun killCode() {
        val k = v.getJSONObject("KillCode")
        assertContentEquals(k.hex("Hash"), Words.killHash(k.getString("Input")))
    }

    @Test
    fun files() {
        val f = v.getJSONObject("File")
        val key = f.hex("Key")
        val cases = f.getJSONArray("Cases")
        for (i in 0 until cases.length()) {
            val c = cases.getJSONObject(i)
            val plain = ByteArray(c.getInt("Size")) { it.toByte() }
            val ct = ByteArrayOutputStream()
            val sum = FileCrypto.encrypt(key, ByteArrayInputStream(plain), ct)
            assertEquals(c.getInt("CipherSize"), ct.size(), "size ${plain.size}")
            assertContentEquals(c.hex("CipherSHA256"), sum, "size ${plain.size}")
            val back = ByteArrayOutputStream()
            FileCrypto.decrypt(key, ByteArrayInputStream(ct.toByteArray()), back)
            assertContentEquals(plain, back.toByteArray())
        }
    }
}

fun unhex(s: String): ByteArray = ByteArray(s.length / 2) { s.substring(2 * it, 2 * it + 2).toInt(16).toByte() }
